package com.nigson.experience.files;
import java.util.*;import jakarta.servlet.http.HttpServletRequest;import org.springframework.http.*;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.web.bind.annotation.*;import tools.jackson.databind.JsonNode;import com.nigson.shared.observability.WireContext;import com.nigson.shared.problem.*;import com.nigson.shared.security.PrivateWorkload;
@RestController public final class ExperienceFileController {
 private final ExperienceFileService service;public ExperienceFileController(ExperienceFileService s){service=s;}
 private PrivateWorkload.Proof proof(){var a=SecurityContextHolder.getContext().getAuthentication();if(a==null||!a.isAuthenticated())throw new Problem.Failure(ProblemCode.AUTH_REQUIRED);if(!(a.getPrincipal() instanceof PrivateWorkload.Proof p))throw new Problem.Failure(ProblemCode.ACCESS_DENIED);return p;}
 private static String header(HttpServletRequest r,String n){var h=Collections.list(r.getHeaders(n));if(h.size()!=1||h.getFirst().isBlank()||h.getFirst().length()>100)throw ApiValues.invalid();return h.getFirst();}
 private static UUID corr(){var w=WireContext.current();return w==null?WireContext.correlation(null):w.correlationId;}
 private static void query(HttpServletRequest r){if(!r.getParameterMap().isEmpty())throw ApiValues.invalid();}
 @PostMapping(value="/api/v1/experience/files/uploads",consumes="application/json",produces="application/json") public ResponseEntity<FileValues.UploadResult> upload(HttpServletRequest r,@RequestBody JsonNode b){query(r);var v=service.upload(proof(),b,header(r,"Idempotency-Key"),corr());return ResponseEntity.status(201).header("Cache-Control","no-store").eTag("0").body(v);}
 @PostMapping(value="/api/v1/experience/files/{id}/completion",consumes="application/json",produces="application/json") public ResponseEntity<FileValues.Asset> complete(HttpServletRequest r,@PathVariable String id,@RequestBody JsonNode b){query(r);var v=service.complete(proof(),ApiValues.uuid(id),ApiValues.version(header(r,"If-Match")),b,header(r,"Idempotency-Key"),corr());return ResponseEntity.accepted().header("Cache-Control","no-store").eTag(Long.toString(v.version())).body(v);}
 @GetMapping(value="/api/v1/experience/files/{id}/download",produces="application/json") public ResponseEntity<FileValues.Download> download(HttpServletRequest r,@PathVariable String id)throws java.io.IOException{query(r);if(r.getInputStream().read()!=-1)throw ApiValues.invalid();return ResponseEntity.ok().header("Cache-Control","no-store").body(service.download(proof(),ApiValues.uuid(id),corr()));}
 @PostMapping(value="/internal/v1/files/{id}/scan-result",consumes="application/json",produces="application/json") public ResponseEntity<FileValues.Asset> scan(HttpServletRequest r,@PathVariable String id,@RequestBody JsonNode b){query(r);var v=service.scan(proof(),ApiValues.uuid(id),ApiValues.version(header(r,"If-Match")),b,header(r,"Idempotency-Key"),corr());return ResponseEntity.ok().header("Cache-Control","no-store").eTag(Long.toString(v.version())).body(v);}
}
